+        srcList.src2 = curCand[candPairWidth];
+        srcList.src3 = curCand[2 * candPairWidth];
+        srcList.src4 = curCand[3 * candPairWidth];
+        MrgSort(tmpCand, srcList, tailPrm);
+        PipeBarrier<PIPE_V>();
+        QLIV2ServiceVec::VecCopyExact(curCand, tmpCand, candPairWidth);
+        PipeBarrier<PIPE_V>();
